update public.themen set titel = 'Klima und Energie', kurzfassung = 'Kein Programm fordert ausdrücklich einen schnelleren Anstieg des CO2-Preises. Drei lehnen ihn ab.', sortierung = 2 where id = '2a2cf39a-2cac-490e-bc3f-6557b9efb890';
update public.themen set titel = 'Rente und Alterssicherung', kurzfassung = 'Fast alle Programme lehnen eine weitere Anhebung des Rentenalters ab, eines will einen frei wählbaren Eintritt.', sortierung = 3 where id = 'd864065a-5d5c-4ad4-8149-645b4a1602eb';
update public.fragen set frage = 'Soll die Mietpreisbremse über 2029 hinaus verlängert werden?', kurz = 'Mietpreisbremse', sortierung = 1 where id = 'c2fcc20d-f7ff-4f12-b03a-7a4dce5ba1f8';
