insert into public.positionen (frage_id, partei_id, haltung, zusammenfassung, quelle_text, quelle_seite, auszug, aenderung, status, erstellt_von, geprueft)
  values ('c2fcc20d-f7ff-4f12-b03a-7a4dce5ba1f8', '27cb31a1-5427-4aa3-9c38-3998d3d6ccf6', 'keine_angabe', 'Keine Fundstelle zur Mietpreisbremse. Das Programm bekennt sich allgemein zu Regeln zur Miethöhe als Teil des Mieterschutzes (nächstgelegene Stelle).', 'Gemeinsames Wahlprogramm von CDU und CSU 2025, gedruckte Seite 71', 73, 'Deutschland ist Mieterland. Wir stehen für einen wirksamen und angemessenen Mieterschutz – dazu gehören auch die Regeln zur Miethöhe.', null, 'veroeffentlicht', 'agent', 'nein');
insert into public.positionen (frage_id, partei_id, haltung, zusammenfassung, quelle_text, quelle_seite, auszug, aenderung, status, erstellt_von, geprueft)
  values ('c2fcc20d-f7ff-4f12-b03a-7a4dce5ba1f8', '82a589fb-b9bf-4a06-91d5-2eb2be2d0df4', 'keine_angabe', 'Keine Fundstelle zur Mietpreisbremse. Das Programm bekennt sich allgemein zu Regeln zur Miethöhe als Teil des Mieterschutzes (nächstgelegene Stelle).', 'Gemeinsames Wahlprogramm von CDU und CSU 2025, gedruckte Seite 71', 73, 'Deutschland ist Mieterland. Wir stehen für einen wirksamen und angemessenen Mieterschutz – dazu gehören auch die Regeln zur Miethöhe.', null, 'veroeffentlicht', 'agent', 'nein');
insert into public.positionen (frage_id, partei_id, haltung, zusammenfassung, quelle_text, quelle_seite, auszug, aenderung, status, erstellt_von, geprueft)
  values ('c2fcc20d-f7ff-4f12-b03a-7a4dce5ba1f8', '32ad76bd-db22-420d-89c2-0ba593d4f289', 'dafuer', 'Will die Mietpreisbremse unbefristet gelten lassen und auf Wohnungen ausweiten, die bis 2019 bezogen wurden.', 'Wahlprogramm 2025', 20, 'Die Mietpreisbremse soll unbefristet und auch für Immobilien, die bis 2019 bezogen wurden, gelten, um langfristig für stabile und bezahlbare Mieten in angespannten Wohnungsmärkten zu sorgen. Wir werden dafür sorgen, dass die Mietpreisbremse nicht durch zum Beispiel (teil-)möblierte und befristete Wohnungsangebote umgangen werden kann.', 'Mietpreisbremse entfristen, auf Wohnungen mit Erstbezug bis 2019 ausweiten und Umgehung über möblierte oder befristete Vermietung unterbinden.', 'veroeffentlicht', 'agent', 'nein');
insert into public.positionen (frage_id, partei_id, haltung, zusammenfassung, quelle_text, quelle_seite, auszug, aenderung, status, erstellt_von, geprueft)
  values ('c2fcc20d-f7ff-4f12-b03a-7a4dce5ba1f8', '88c662bc-56a3-47e1-a72f-9bd13342e487', 'dafuer', 'Wollen die Mietpreisbremse verlängern und durch den Wegfall von Ausnahmen verschärfen.', 'Wahlprogramm 2025', 69, 'Wir werden die Mietpreisbremse verlängern und sie durch die Abschaffung von Ausnahmen verschärfen. Wir wollen die Mietpreisbremse außerdem bereits auf Wohnungen anwenden, die älter als fünf Jahre sind.', 'Ausnahmen streichen und die Bremse auf Wohnungen anwenden, die älter als fünf Jahre sind.', 'veroeffentlicht', 'agent', 'nein');
insert into public.positionen (frage_id, partei_id, haltung, zusammenfassung, quelle_text, quelle_seite, auszug, aenderung, status, erstellt_von, geprueft)
  values ('c2fcc20d-f7ff-4f12-b03a-7a4dce5ba1f8', '605a6b11-ae88-41f0-af95-ed4c457aac32', 'dagegen', 'Hält die Mietpreisbremse für ein Investitionshemmnis und will sie auslaufen lassen.', 'Wahlprogramm 2025, gedruckte Seite 43', 44, 'Die Mietpreisbremse ist nachweislich eine Investitionsbremse. Deshalb lassen wir sie auslaufen.', 'Mietpreisbremse auslaufen lassen.', 'veroeffentlicht', 'agent', 'nein');
insert into public.positionen (frage_id, partei_id, haltung, zusammenfassung, quelle_text, quelle_seite, auszug, aenderung, status, erstellt_von, geprueft)
  values ('c2fcc20d-f7ff-4f12-b03a-7a4dce5ba1f8', '9823eced-6ef4-485f-a509-dd754f98f4ba', 'dagegen', 'Lehnt die Mietpreisbremse als staatliche Überregulierung und Investitionshemmnis ab.', 'Wahlprogramm 2025, gedruckte Seite 38', 39, 'Die AfD steht für ein ausgewogenes Mietrecht und lehnt staatliche Überregulierungen sowie Investitionshemmnisse wie die Mietpreisbremse oder den Mietendeckel ab.', null, 'veroeffentlicht', 'agent', 'nein');
insert into public.positionen (frage_id, partei_id, haltung, zusammenfassung, quelle_text, quelle_seite, auszug, aenderung, status, erstellt_von, geprueft)
  values ('c2fcc20d-f7ff-4f12-b03a-7a4dce5ba1f8', 'e257cff5-1d3a-472e-99f9-2b8a28ee9f70', 'teilweise', 'Hält die Mietpreisbremse für zu schwach, kritisiert, dass sie nicht verlängert und verschärft wurde, und fordert stattdessen einen strengeren bundesweiten Mietendeckel.', 'Wahlprogramm 2025', 8, 'Die Ampel hat es nicht einmal geschafft, die Mietpreisbremse zu verlängern, geschweige denn sie zu verschärfen.', 'Bundesweiter Mietendeckel und als Sofortmaßnahme Ausschluss von Mieterhöhungen für sechs Jahre.', 'veroeffentlicht', 'agent', 'nein');
insert into public.positionen (frage_id, partei_id, haltung, zusammenfassung, quelle_text, quelle_seite, auszug, aenderung, status, erstellt_von, geprueft)
  values ('c2fcc20d-f7ff-4f12-b03a-7a4dce5ba1f8', 'f7d4cb3d-ef85-442c-9a9f-f7ed9609984e', 'dagegen', 'Will die Mietpreisbremse durch eine strengere Regel ersetzen, einen bundesweiten Mietendeckel. Das „dagegen“ heißt hier: mehr Regulierung, nicht weniger.', 'Wahlprogramm 2025', 28, 'Wir fordern einen bundesweiten Mietendeckel statt einer wirkungslosen Mietpreisbremse.', 'Mietendeckel statt Mietpreisbremse; Mieten in überteuerten Regionen bis Ende des Jahrzehnts einfrieren.', 'veroeffentlicht', 'agent', 'nein');
insert into public.positionen (frage_id, partei_id, haltung, zusammenfassung, quelle_text, quelle_seite, auszug, aenderung, status, erstellt_von, geprueft)
  values ('c2fcc20d-f7ff-4f12-b03a-7a4dce5ba1f8', 'a2bbca41-0896-4a23-9a83-5c77b8ce9f4b', 'keine_angabe', 'Keine Fundstelle zur Mietpreisbremse. Das Programm lehnt nur einen Mietendeckel ab und setzt auf Wohnungsbau (nächstgelegene Stelle).', 'Wahlprogramm 2025, gedruckte Seite 83', 85, 'Statt für einen investitionsfeindlichen Mietendeckel stehen wir für zweckgebundene Bürgeranleihen nach Münchener Vorbild.', null, 'veroeffentlicht', 'agent', 'nein');
insert into public.positionen (frage_id, partei_id, haltung, zusammenfassung, quelle_text, quelle_seite, auszug, aenderung, status, erstellt_von, geprueft)
