insert into public.positionen (frage_id, partei_id, haltung, zusammenfassung, quelle_text, quelle_seite, auszug, aenderung, status, erstellt_von, geprueft)
  values ('584471ef-30b5-4334-a3d7-e51f20d929aa', '27cb31a1-5427-4aa3-9c38-3998d3d6ccf6', 'teilweise', 'Will die CO2-Bepreisung zum Leitinstrument ausbauen und die Einnahmen zurückgeben, nennt aber keinen schnelleren Preispfad.', 'Gemeinsames Wahlprogramm von CDU und CSU 2025, gedruckte Seite 22', 24, 'Die CO2-Bepreisung bauen wir im Instrumentenmix zum Leitinstrument aus und geben deren Einnahmen an Verbraucher und Wirtschaft zurück.', 'Klimabonus einführen; mit den CO2-Einnahmen zuerst Stromsteuer und Netzentgelte senken.', 'veroeffentlicht', 'agent', 'nein');
