  values ('584471ef-30b5-4334-a3d7-e51f20d929aa', '82a589fb-b9bf-4a06-91d5-2eb2be2d0df4', 'teilweise', 'Will die CO2-Bepreisung zum Leitinstrument ausbauen und die Einnahmen zurückgeben, nennt aber keinen schnelleren Preispfad.', 'Gemeinsames Wahlprogramm von CDU und CSU 2025, gedruckte Seite 22', 24, 'Die CO2-Bepreisung bauen wir im Instrumentenmix zum Leitinstrument aus und geben deren Einnahmen an Verbraucher und Wirtschaft zurück.', 'Klimabonus einführen; mit den CO2-Einnahmen zuerst Stromsteuer und Netzentgelte senken.', 'veroeffentlicht', 'agent', 'nein');
insert into public.positionen (frage_id, partei_id, haltung, zusammenfassung, quelle_text, quelle_seite, auszug, aenderung, status, erstellt_von, geprueft)
  values ('584471ef-30b5-4334-a3d7-e51f20d929aa', '32ad76bd-db22-420d-89c2-0ba593d4f289', 'teilweise', 'Hält am beschlossenen Preispfad fest und will ab 2027 eine Überforderung verhindern, etwa mit einem Klimageld.', 'Wahlprogramm 2025', 33, 'Der bereits gesetzlich beschlossene CO2-Preis pro Tonne von 55 Euro in 2025 und maximal 65 Euro in 2026 gilt. Wenn ab 2027 die europäische Regelung in Kraft tritt, werden wir durch geeignete Maßnahmen auf europäischer und nationaler Ebene (zum Beispiel Klimageld) dafür Sorge tragen, dass niemand überfordert wird.', 'Entlastung etwa durch ein Klimageld ab 2027.', 'veroeffentlicht', 'agent', 'nein');
insert into public.positionen (frage_id, partei_id, haltung, zusammenfassung, quelle_text, quelle_seite, auszug, aenderung, status, erstellt_von, geprueft)
  values ('584471ef-30b5-4334-a3d7-e51f20d929aa', '88c662bc-56a3-47e1-a72f-9bd13342e487', 'teilweise', 'Wollen den europäischen Emissionshandel wie geplant umsetzen und die Einnahmen als Klimageld auszahlen, fordern aber keinen schnelleren Anstieg.', 'Wahlprogramm 2025', 38, 'Dazu gehört die Umsetzung der Emissionshandelssysteme auf europäischer Ebene wie geplant. So stärken wir den CO₂-Preis als einen zentralen Hebel für mehr Klimaschutz in Deutschland und Europa.', 'Sozial gestaffeltes Klimageld, das mit den Einnahmen steigt (S. 40).', 'veroeffentlicht', 'agent', 'nein');
insert into public.positionen (frage_id, partei_id, haltung, zusammenfassung, quelle_text, quelle_seite, auszug, aenderung, status, erstellt_von, geprueft)
  values ('584471ef-30b5-4334-a3d7-e51f20d929aa', '605a6b11-ae88-41f0-af95-ed4c457aac32', 'teilweise', 'Will den EU-Emissionshandel mit marktgebildetem Preis und eine Klimadividende pro Kopf, nennt aber keinen beschleunigten Pfad.', 'Wahlprogramm 2025, gedruckte Seite 39', 40, 'Wir Freie Demokraten wollen eine Klimadividende einführen, um Einnahmen aus dem Emissionshandel direkt und pauschal pro Kopf an die Bürgerinnen und Bürger zurückzuzahlen.', 'Klimadividende pro Kopf; Klimaneutralitätsziel von 2045 auf 2050 verschieben.', 'veroeffentlicht', 'agent', 'nein');
insert into public.positionen (frage_id, partei_id, haltung, zusammenfassung, quelle_text, quelle_seite, auszug, aenderung, status, erstellt_von, geprueft)
  values ('584471ef-30b5-4334-a3d7-e51f20d929aa', '9823eced-6ef4-485f-a509-dd754f98f4ba', 'dagegen', 'Will alle CO2-Abgaben ersatzlos abschaffen.', 'Wahlprogramm 2025, gedruckte Seite 57', 58, 'Wir fordern eine ersatzlose Abschaffung der CO₂-Abgaben.', 'CO2-Abgaben abschaffen.', 'veroeffentlicht', 'agent', 'nein');
insert into public.positionen (frage_id, partei_id, haltung, zusammenfassung, quelle_text, quelle_seite, auszug, aenderung, status, erstellt_von, geprueft)
  values ('584471ef-30b5-4334-a3d7-e51f20d929aa', 'e257cff5-1d3a-472e-99f9-2b8a28ee9f70', 'dagegen', 'Lehnt den Emissionshandel für Wärme und Verkehr ab und will dort feste Emissionsgrenzen statt eines CO2-Preises.', 'Wahlprogramm 2025', 33, 'Wir lehnen den Emissionshandel in den Sektoren Wärme und Verkehr (ETS-2) ab: Stattdessen müssen verbindliche Klimaziele und Emissionsgrenzen gesetzt werden.', 'Soziales Klimageld von 320 Euro pro Person und Jahr (S. 7).', 'veroeffentlicht', 'agent', 'nein');
insert into public.positionen (frage_id, partei_id, haltung, zusammenfassung, quelle_text, quelle_seite, auszug, aenderung, status, erstellt_von, geprueft)
  values ('584471ef-30b5-4334-a3d7-e51f20d929aa', 'f7d4cb3d-ef85-442c-9a9f-f7ed9609984e', 'dagegen', 'Will den CO2-Preis abschaffen.', 'Wahlprogramm 2025', 10, 'Den CO2-Preis, der alles teurer macht, ohne dass es für die meisten Menschen Alternativen gibt, wollen wir abschaffen.', 'CO2-Preis abschaffen; EU-Emissionshandel globalisieren oder abschaffen (S. 11).', 'veroeffentlicht', 'agent', 'nein');
insert into public.positionen (frage_id, partei_id, haltung, zusammenfassung, quelle_text, quelle_seite, auszug, aenderung, status, erstellt_von, geprueft)
  values ('584471ef-30b5-4334-a3d7-e51f20d929aa', 'a2bbca41-0896-4a23-9a83-5c77b8ce9f4b', 'keine_angabe', 'Keine Fundstelle zum allgemeinen CO2-Preis. Nur für die Luftfahrt befürwortet das Programm eine langfristig festgeschriebene Bepreisung (nächstgelegene Stelle).', 'Wahlprogramm 2025, gedruckte Seite 37', 39, 'Verlässliche politische Rahmenbedingungen, die eine Bepreisung der CO2 -Äquivalente über einen Zertifikate-Handel langfristig festschreiben, schaffen die Voraussetzung dafür, dass die Branche in die Entwicklung und den Umstieg investiert.', null, 'veroeffentlicht', 'agent', 'nein');
insert into public.positionen (frage_id, partei_id, haltung, zusammenfassung, quelle_text, quelle_seite, auszug, aenderung, status, erstellt_von, geprueft)
  values ('584471ef-30b5-4334-a3d7-e51f20d929aa', 'e338320e-ac96-4322-b022-3ccc0f3fe507', 'teilweise', 'Will den steigenden CO2-Preis mit einem Pro-Kopf-Klimageld sozialverträglich machen.', 'Wahlprogramm 2025', 23, 'Wir wollen ein Pro-Kopf-Klimageld, das private Haushalte entlastet, umweltbewusstes Verhalten belohnt und die steigende CO2-Steuer so sozialverträglich ausgestalten.', 'Pro-Kopf-Klimageld nach österreichischem Vorbild.', 'veroeffentlicht', 'agent', 'nein');
insert into public.positionen (frage_id, partei_id, haltung, zusammenfassung, quelle_text, quelle_seite, auszug, aenderung, status, erstellt_von, geprueft)
  values ('95c54175-3b25-4055-a704-52ebec90696f', '27cb31a1-5427-4aa3-9c38-3998d3d6ccf6', 'dagegen', 'Hält an der geltenden Regelung fest, also an der Rente mit 67 ab 2031, ohne weitere Anhebung.', 'Gemeinsames Wahlprogramm von CDU und CSU 2025, gedruckte Seite 32', 34, 'An der bestehenden gesetzlichen Regelung zum Renteneintrittsalter halten wir fest. Die Regelung für besonders langjährige Versicherte mit 45 Versicherungsjahren behalten wir mit Blick auf die Planungssicherheit für Unternehmen und rentennahe Jahrgänge bei.', 'Aktivrente für freiwilliges Weiterarbeiten (S. 33).', 'veroeffentlicht', 'agent', 'nein');
insert into public.positionen (frage_id, partei_id, haltung, zusammenfassung, quelle_text, quelle_seite, auszug, aenderung, status, erstellt_von, geprueft)
  values ('95c54175-3b25-4055-a704-52ebec90696f', '82a589fb-b9bf-4a06-91d5-2eb2be2d0df4', 'dagegen', 'Hält an der geltenden Regelung fest, also an der Rente mit 67 ab 2031, ohne weitere Anhebung.', 'Gemeinsames Wahlprogramm von CDU und CSU 2025, gedruckte Seite 32', 34, 'An der bestehenden gesetzlichen Regelung zum Renteneintrittsalter halten wir fest. Die Regelung für besonders langjährige Versicherte mit 45 Versicherungsjahren behalten wir mit Blick auf die Planungssicherheit für Unternehmen und rentennahe Jahrgänge bei.', 'Aktivrente für freiwilliges Weiterarbeiten (S. 33).', 'veroeffentlicht', 'agent', 'nein');
insert into public.positionen (frage_id, partei_id, haltung, zusammenfassung, quelle_text, quelle_seite, auszug, aenderung, status, erstellt_von, geprueft)
  values ('95c54175-3b25-4055-a704-52ebec90696f', '32ad76bd-db22-420d-89c2-0ba593d4f289', 'dagegen', 'Lehnt eine Anhebung der Regelaltersgrenze ab.', 'Wahlprogramm 2025', 25, 'Das haben sich gerade Menschen verdient, die früh begonnen haben zu arbeiten. Eine Anhebung der Regelaltersgrenze lehnen wir ab.', null, 'veroeffentlicht', 'agent', 'nein');
insert into public.positionen (frage_id, partei_id, haltung, zusammenfassung, quelle_text, quelle_seite, auszug, aenderung, status, erstellt_von, geprueft)
  values ('95c54175-3b25-4055-a704-52ebec90696f', '88c662bc-56a3-47e1-a72f-9bd13342e487', 'dagegen', 'Halten an der Rente mit 67 fest und wollen freiwilliges längeres Arbeiten erleichtern.', 'Wahlprogramm 2025', 98, 'Wir halten an der Rente mit 67 fest. Aber wir schaffen Anreize und machen es den Menschen leichter, länger zu arbeiten, wenn sie dies wollen, auch über die Regelaltersgrenze hinaus.', null, 'veroeffentlicht', 'agent', 'nein');
insert into public.positionen (frage_id, partei_id, haltung, zusammenfassung, quelle_text, quelle_seite, auszug, aenderung, status, erstellt_von, geprueft)
  values ('95c54175-3b25-4055-a704-52ebec90696f', '605a6b11-ae88-41f0-af95-ed4c457aac32', 'teilweise', 'Will keine feste Anhebung, sondern einen frei wählbaren Renteneintritt nach schwedischem Vorbild.', 'Wahlprogramm 2025, gedruckte Seite 20', 21, 'Wir Freie Demokraten stehen für einen wirklich flexiblen Renteneintritt. Die Menschen sollen nach schwedischem Vorbild künftig selbst entscheiden, wann der Ruhestand beginnt, sofern dann keine Sozialleistungen beantragt werden müssen.', 'Flexibler Renteneintritt nach schwedischem Vorbild.', 'veroeffentlicht', 'agent', 'nein');
insert into public.positionen (frage_id, partei_id, haltung, zusammenfassung, quelle_text, quelle_seite, auszug, aenderung, status, erstellt_von, geprueft)
  values ('95c54175-3b25-4055-a704-52ebec90696f', '9823eced-6ef4-485f-a509-dd754f98f4ba', 'keine_angabe', 'Keine Fundstelle zur Regelaltersgrenze. Das Programm fordert einen flexiblen Renteneintritt und Anreize für freiwilliges längeres Arbeiten (nächstgelegene Stelle).', 'Wahlprogramm 2025, gedruckte Seite 18', 19, 'Wir wollen der Rentenversicherung mehr Beitragszahler zuführen, die Verrentung flexibler und gerechter gestalten und Anreize für eine freiwillige Verlängerung der Lebensarbeitszeit setzen, indem wir:', 'Flexibles Renteneintrittsalter, abschlagsfrei nach 45 beitragsberechtigten Arbeitsjahren.', 'veroeffentlicht', 'agent', 'nein');
insert into public.positionen (frage_id, partei_id, haltung, zusammenfassung, quelle_text, quelle_seite, auszug, aenderung, status, erstellt_von, geprueft)
  values ('95c54175-3b25-4055-a704-52ebec90696f', 'e257cff5-1d3a-472e-99f9-2b8a28ee9f70', 'dagegen', 'Will die Regelaltersgrenze auf 65 Jahre senken.', 'Wahlprogramm 2025', 15, 'Die Rente erst ab 67 bedeutet Rentenkürzungen für alle, insbesondere in Berufen, in denen Erwerbstätige nicht so lange durchhalten können. Wir fordern eine Regelaltersgrenze von 65 Jahren.', 'Regelaltersgrenze 65; nach 40 Beitragsjahren abschlagsfrei ab 60.', 'veroeffentlicht', 'agent', 'nein');
insert into public.positionen (frage_id, partei_id, haltung, zusammenfassung, quelle_text, quelle_seite, auszug, aenderung, status, erstellt_von, geprueft)
  values ('95c54175-3b25-4055-a704-52ebec90696f', 'f7d4cb3d-ef85-442c-9a9f-f7ed9609984e', 'dagegen', 'Lehnt eine weitere Erhöhung des Renteneintrittsalters ab.', 'Wahlprogramm 2025', 23, 'Forderungen, das Renteneintrittsalter weiter zu erhöhen, erteilen wir eine klare Absage.', null, 'veroeffentlicht', 'agent', 'nein');
insert into public.positionen (frage_id, partei_id, haltung, zusammenfassung, quelle_text, quelle_seite, auszug, aenderung, status, erstellt_von, geprueft)
  values ('95c54175-3b25-4055-a704-52ebec90696f', 'a2bbca41-0896-4a23-9a83-5c77b8ce9f4b', 'dagegen', 'Lehnt eine Erhöhung des Rentenalters ab.', 'Wahlprogramm 2025, gedruckte Seite 67', 69, 'Wir sprechen uns klar gegen eine Erhöhung des Rentenalters aus.', 'Volle Rente abschlagsfrei nach 45 Beitragsjahren; Rentenniveau nicht unter 48 Prozent.', 'veroeffentlicht', 'agent', 'nein');
insert into public.positionen (frage_id, partei_id, haltung, zusammenfassung, quelle_text, quelle_seite, auszug, aenderung, status, erstellt_von, geprueft)
  values ('95c54175-3b25-4055-a704-52ebec90696f', 'e338320e-ac96-4322-b022-3ccc0f3fe507', 'dagegen', 'Will keine Erhöhung des Renteneintrittsalters.', 'Wahlprogramm 2025', 8, 'Wir wollen keine Erhöhung des Renteneintrittsalters.', null, 'veroeffentlicht', 'agent', 'nein');
insert into public.argumente (id, frage_id, richtung, text, quelle_text, quelle_url, ist_demo, status, erstellt_von, geprueft)
  values ('59458aad-fc36-406b-8f8e-ff2800db3865', 'c2fcc20d-f7ff-4f12-b03a-7a4dce5ba1f8', 'dafuer', 'Eine im Auftrag des Bundesjustizministeriums erstellte Studie des DIW kam zu dem Ergebnis, dass sich der Mietanstieg durch die Mietpreisbremse verlangsamt hat.', 'Wissenschaftliche Dienste des Bundestages, WD 7 - 3000 - 086/19 (2019)', 'https://bundestag.de/resource/blob/651090/7f66ea9edc5dd92fbafb8197b783eeea/WD-7-086-19-pdf-data.pdf', false, 'veroeffentlicht', 'agent', 'nein')
  on conflict (id) do update set frage_id = excluded.frage_id, text = excluded.text, richtung = excluded.richtung, quelle_text = excluded.quelle_text,
    quelle_url = excluded.quelle_url, ist_demo = false, status = excluded.status, erstellt_von = excluded.erstellt_von, geprueft = excluded.geprueft;
insert into public.argumente (id, frage_id, richtung, text, quelle_text, quelle_url, ist_demo, status, erstellt_von, geprueft)
  values ('d1c4e2a0-6b1f-4c39-9a57-1f0e8b3c2d41', 'c2fcc20d-f7ff-4f12-b03a-7a4dce5ba1f8', 'dagegen', 'Der Wissenschaftliche Beirat beim Bundeswirtschaftsministerium bescheinigte der Mietpreisbremse mangelnde Wirksamkeit; Effekte für untere Einkommensschichten seien nicht nachweisbar.', 'Wissenschaftliche Dienste des Bundestages, WD 7 - 3000 - 086/19 (2019)', 'https://bundestag.de/resource/blob/651090/7f66ea9edc5dd92fbafb8197b783eeea/WD-7-086-19-pdf-data.pdf', false, 'veroeffentlicht', 'agent', 'nein')
  on conflict (id) do update set frage_id = excluded.frage_id, text = excluded.text, richtung = excluded.richtung, quelle_text = excluded.quelle_text,
