insert into public.argumente (id, frage_id, richtung, text, quelle_text, quelle_url, ist_demo, status, erstellt_von, geprueft)
  values ('e7a9b3c5-2d4f-4e61-8b70-3c1d5e9f0a12', '584471ef-30b5-4334-a3d7-e51f20d929aa', 'dafuer', 'Das Umweltbundesamt beziffert die gesellschaftlichen Klimakosten auf rund 350 Euro je Tonne CO2, also deutlich mehr als der derzeitige CO2-Preis.', 'Umweltbundesamt, Gesellschaftliche Kosten von Umweltbelastungen', 'https://www.umweltbundesamt.de/daten/umwelt-wirtschaft/gesellschaftliche-kosten-von-umweltbelastungen', false, 'veroeffentlicht', 'agent', 'nein')
  on conflict (id) do update set frage_id = excluded.frage_id, text = excluded.text, richtung = excluded.richtung, quelle_text = excluded.quelle_text,
    quelle_url = excluded.quelle_url, ist_demo = false, status = excluded.status, erstellt_von = excluded.erstellt_von, geprueft = excluded.geprueft;
insert into public.argumente (id, frage_id, richtung, text, quelle_text, quelle_url, ist_demo, status, erstellt_von, geprueft)
  values ('f2b6d8e0-4a1c-4f73-9e85-6d2c7a0b1e23', '584471ef-30b5-4334-a3d7-e51f20d929aa', 'dagegen', 'Haushalte mit niedrigem Einkommen geben einen größeren Teil ihres Einkommens für Energie und Mobilität aus und werden durch einen steigenden CO2-Preis relativ stärker belastet.', 'DIW Wochenbericht 42/2024', 'https://www.diw.de/de/diw_01.c.917856.de/publikationen/wochenberichte/2024_42_1/.html', false, 'veroeffentlicht', 'agent', 'nein')
  on conflict (id) do update set frage_id = excluded.frage_id, text = excluded.text, richtung = excluded.richtung, quelle_text = excluded.quelle_text,
    quelle_url = excluded.quelle_url, ist_demo = false, status = excluded.status, erstellt_von = excluded.erstellt_von, geprueft = excluded.geprueft;
insert into public.argumente (id, frage_id, richtung, text, quelle_text, quelle_url, ist_demo, status, erstellt_von, geprueft)
  values ('a8c1e3f5-7b2d-4c94-8f06-9e3a1b5c7d34', '95c54175-3b25-4055-a704-52ebec90696f', 'dafuer', 'Weil die Lebenserwartung steigt und viele Babyboomer in Rente gehen, zahlen immer weniger Beschäftigte für immer mehr Rentner; eine Mehrheit des Sachverständigenrats empfiehlt deshalb, das Eintrittsalter an die Lebenserwartung zu koppeln.', 'bpb, Diskussion um Erhöhung des Renteneintrittsalters (14.11.2023)', 'https://www.bpb.de/kurz-knapp/taegliche-dosis-politik/542683/diskussion-um-erhoehung-des-renteneintrittsalters/', false, 'veroeffentlicht', 'agent', 'nein')
  on conflict (id) do update set frage_id = excluded.frage_id, text = excluded.text, richtung = excluded.richtung, quelle_text = excluded.quelle_text,
    quelle_url = excluded.quelle_url, ist_demo = false, status = excluded.status, erstellt_von = excluded.erstellt_von, geprueft = excluded.geprueft;
insert into public.argumente (id, frage_id, richtung, text, quelle_text, quelle_url, ist_demo, status, erstellt_von, geprueft)
  values ('b3d5f7a9-1c3e-4da5-9b17-2f4b6c8e0a45', '95c54175-3b25-4055-a704-52ebec90696f', 'dagegen', 'In vielen Berufen kann aus gesundheitlichen Gründen nicht bis ins hohe Alter gearbeitet werden, und das tatsächliche Renteneintrittsalter liegt schon heute unter dem gesetzlichen.', 'bpb, Diskussion um Erhöhung des Renteneintrittsalters (14.11.2023)', 'https://www.bpb.de/kurz-knapp/taegliche-dosis-politik/542683/diskussion-um-erhoehung-des-renteneintrittsalters/', false, 'veroeffentlicht', 'agent', 'nein')
